646→// shouldCondenseWithOverlapCheck returns true if the session should be condensed
647→// into this commit. Requires both that hasNew is true AND that the session's files
648→// overlap with the committed files with matching content.
649→//
650→// This prevents stale sessions (ACTIVE sessions where the agent was killed, or
651→// ENDED/IDLE sessions with carry-forward files) from being condensed into every
652→// unrelated commit.
653→//
654→// filesTouchedBefore is populated from:
655→//   - state.FilesTouched for IDLE/ENDED sessions (set via SaveStep/SaveTaskStep -> mergeFilesTouched)
656→//   - transcript extraction for ACTIVE sessions when FilesTouched is empty
657→//
658→// When filesTouchedBefore is empty:
659→//   - For ACTIVE sessions: fail-open (trust hasNew) because the agent may be
660→//     mid-turn before any files are saved to state.
661→//   - For IDLE/ENDED sessions: return false because there are no files to
662→//     overlap with the commit.
663→func (h *postCommitActionHandler) shouldCondenseWithOverlapCheck(isActive bool) bool {
664→	if !h.hasNew {
665→		return false
666→	}
667→	if len(h.filesTouchedBefore) == 0 {
668→		return isActive // ACTIVE: fail-open; IDLE/ENDED: no files = no overlap
669→	}
670→	// Only check files that were actually changed in this commit.
671→	// Without this, files that exist in the tree but weren't changed
672→	// would pass the "modified file" check in filesOverlapWithContent
673→	// (because the file exists in the parent tree), causing stale
674→	// sessions to be incorrectly condensed.
675→	var committedTouchedFiles []string
676→	for _, f := range h.filesTouchedBefore {
677→		if _, ok := h.committedFileSet[f]; ok {
678→			committedTouchedFiles = append(committedTouchedFiles, f)
679→		}
680→	}
681→	if len(committedTouchedFiles) == 0 {
682→		return false
683→	}
684→	return filesOverlapWithContent(h.ctx, h.repo, h.shadowBranchName, h.commit, committedTouchedFiles, overlapOpts{
685→		headTree:      h.headTree,
686→		shadowTree:    h.shadowTree,
687→		parentTree:    h.parentTree,
688→		hasParentTree: true,
689→	})
690→}
