// shouldCondenseWithOverlapCheck returns true if the session should be condensed
// into this commit.
//
// For genuinely-active sessions (ACTIVE with recent interaction): always returns
// true when hasNew is true. This handles the case where Turn 1 touched file A
// but Turn 2 commits different files B and C — the overlap check would
// incorrectly reject this because filesTouchedBefore (from Turn 1) doesn't
// overlap with the committed files (from Turn 2).
//
// For stale ACTIVE sessions (agent killed, no recent interaction): falls through
// to the overlap check. Without this guard, a zombie session stuck in ACTIVE
// phase would be condensed into every commit forever.
//
// For IDLE/ENDED sessions: requires both that hasNew is true AND that the
// session's files overlap with the committed files with matching content. This
// prevents stale IDLE/ENDED sessions from being condensed into unrelated commits.
//
// filesTouchedBefore is populated from:
//   - state.FilesTouched for IDLE/ENDED sessions (set via SaveStep/SaveTaskStep -> mergeFilesTouched)
//   - transcript extraction for ACTIVE sessions when FilesTouched is empty
func (h *postCommitActionHandler) shouldCondenseWithOverlapCheck(isActive bool, lastInteraction *time.Time) bool {
	if !h.hasNew {
		return false
	}
	// ACTIVE sessions with recent interaction: skip the overlap check.
	// PrepareCommitMsg already validated this commit is session-related
	// (added trailer). The overlap check is only meaningful when we need
	// heuristic evidence that a commit was related to the session.
	//
	// We check LastInteractionTime to avoid condensing stale ACTIVE sessions
	// (agent killed without Stop hook) into every subsequent commit. A stale
	// session has no recent interaction and falls through to the overlap check.
	if isActive && isRecentInteraction(lastInteraction) {
		return true
	}
	if len(h.filesTouchedBefore) == 0 {
		if isActive {
			return true // ACTIVE without interaction time: fail-open (backward compat)
		}
		return false // IDLE/ENDED: no files tracked = no overlap evidence
	}

