// activeSessionInteractionThreshold is the maximum age of LastInteractionTime
// for an ACTIVE session to be considered "genuinely active" (agent currently running).
// Sessions with interactions older than this are treated as stale (agent was killed)
// and must pass the overlap check to be condensed.
//
// This is intentionally generous (1 hour) to avoid false positives — long agent turns
// (e.g., complex refactoring tasks) can take many minutes. An agent killed without
// the Stop hook will have its LastInteractionTime frozen at the last TurnStart.
const activeSessionInteractionThreshold = 1 * time.Hour

// isRecentInteraction returns true if lastInteraction is non-nil and within
// activeSessionInteractionThreshold of now.
func isRecentInteraction(lastInteraction *time.Time) bool {
	return lastInteraction != nil && time.Since(*lastInteraction) < activeSessionInteractionThreshold
}

