226→// ForEachAgent runs fn as a parallel subtest for every registered agent.
227→// It handles repo setup, concurrency gating, context timeout, and cleanup.
228→// The timeout is scaled by each agent's TimeoutMultiplier.
229→//
230→// If RunPrompt detects a transient API error (e.g. rate limit, token refresh
231→// failure), it panics with errScenarioRestart. ForEachAgent recovers from the
232→// panic and restarts the entire scenario with a fresh repository, up to
233→// maxScenarioRestarts times. This avoids stale CLI session state from the
234→// failed attempt poisoning the retry.
235→func ForEachAgent(t *testing.T, timeout time.Duration, fn func(t *testing.T, s *RepoState, ctx context.Context)) {
236→	t.Helper()
237→	t.Parallel()
238→	all := agents.All()
239→	if len(all) == 0 {
240→		t.Skip("no agents registered (check E2E_AGENT filter)")
241→	}
242→	for _, agent := range all {
243→		t.Run(agent.Name(), func(t *testing.T) {
244→			// Use the global test deadline for slot wait so we don't
245→			// skip prematurely — only bail if the whole binary is dying.
246→			slotCtx := context.Background()
247→			if deadline, ok := t.Deadline(); ok {
248→				var cancel context.CancelFunc
249→				slotCtx, cancel = context.WithDeadline(slotCtx, deadline)
250→				defer cancel()
251→			}
252→			if err := agents.AcquireSlot(slotCtx, agent); err != nil {
253→				t.Fatalf("timed out waiting for agent slot: %v", err)
254→			}
255→			defer agents.ReleaseSlot(agent)
256→
257→			// Per-test timeout starts after slot is acquired, scaled
258→			// by the agent's multiplier (e.g. 2.5× for gemini).
259→			scaled := time.Duration(float64(timeout) * agent.TimeoutMultiplier())
260→
261→			var prevState *RepoState
262→			for attempt := range maxScenarioRestarts + 1 {
263→				s := SetupRepo(t, agent)
264→				ctx, cancel := context.WithTimeout(context.Background(), scaled)
265→
266→				// On restart, suppress artifact capture from the previous
267→				// failed attempt so it doesn't overwrite the final one.
268→				if prevState != nil {
269→					prevState.skipArtifacts = true
270→				}
271→
272→				restarted := runScenario(t, s, ctx, fn)
273→				cancel()
274→
275→				if !restarted {
276→					return
277→				}
278→				prevState = s
279→				if attempt >= maxScenarioRestarts {
280→					t.Fatalf("exhausted %d scenario attempts due to transient API errors", maxScenarioRestarts+1)
281→				}
282→				t.Logf("transient error, restarting scenario (attempt %d/%d)", attempt+2, maxScenarioRestarts+1)
283→			}
284→		})
285→	}
286→}
